      {
        "code": "H280",
        "text": "고압가스: 가열하면 폭발할 수 있음",
        "line": "p1:L23"
      },
      {
        "code": "H335",
        "text": "호흡기 자극을 일으킬 수 있음",
        "line": "p1:L24"
      },
      {
        "code": "H336",
        "text": "졸음 또는 현기증을 일으킬 수 있음",
        "line": "p1:L25"
      },
      {
        "code": "H420",
        "text": "대기 상층부의 오존층을 파괴하여 공공의 건강 및 환경에 유해함",
        "line": "p1:L26"
      }
    ],
    "p_statements": [
      {
        "code": "P261",
        "type": "예방",
        "text": "가스의 흡입을 피하시오.",
        "line": "p1:L28"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p1:L29"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관/의사의 진찰을 받으시오.",
        "line": "p1:L30"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면: 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p1:L31"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치를 하여 저장하시오.",
        "line": "p1:L33"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하시오. 용기를 단단히 밀폐하시오.",
        "line": "p1:L34"
      },
      {
        "code": "P410+P403",
        "type": "저장",
        "text": "직사광선을 피하시오. 환기가 잘 되는 곳에 보관하시오.",
        "line": "p1:L35"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물 관련 법령에 따라 내용물/용기를 폐기하시오.",
        "line": "p1:L36"
      },
      {
        "code": "P502",
        "type": "폐기",
        "text": "제조자 또는 공급자가 제공한 재생 또는 재활용에 대한 정보를 참조하시오.",
        "line": "p1:L37"
      }
    ],
    "other_hazards": [
      {
        "key": "분진폭발 위험성",
        "value": "자료 없음",
        "line": "p2:L6"
      }
    ]
  ,
